import{_ as r,a0 as p,w as i,s as u,I as s,x as l,a1 as e,A as n,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"為什麼你應該成為一名系統管理員？ | LCTT x X-CMD","titleTemplate":false,"description":"為什麼你應該成為一名系統管理員？ | LCTT (201708) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"為什麼你應該成為一名系統管理員？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"為什麼你應該成為一名系統管理員？ | LCTT (201708) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201708/20170717 Why you should be a sysadmin","title":"為什麼你應該成為一名系統管理員？","tag":"201708","desc":""},"relativePath":"201708/20170717 Why you should be a sysadmin.md","filePath":"[post].md"}'),d={name:"201708/20170717 Why you should be a sysadmin.md"};function m(f,t,T,y,b,g){const o=p("Link");return i(),u("div",null,[t[19]||(t[19]=s("h1",{id:"為什麼你應該成為一名系統管理員",tabindex:"-1"},[l("為什麼你應該成為一名系統管理員？ "),s("a",{class:"header-anchor",href:"#為什麼你應該成為一名系統管理員","aria-label":"Permalink to “為什麼你應該成為一名系統管理員？”"},"​")],-1)),t[20]||(t[20]=s("blockquote",null,[s("p",null,"網絡和系統管理工作工資高、崗位多。")],-1)),t[21]||(t[21]=s("p",null,[s("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/images/life/sysadmin_uncleserver.jpeg?itok=Tc9LAT7N",alt:"為什麼你應該成為一名系統管理員",title:"Why you should be a sysadmin"})],-1)),t[22]||(t[22]=s("p",null,"我們為秩序而戰，而服務器大叔則需要你成為系統管理員。",-1)),s("p",null,[t[1]||(t[1]=l("這是個很好的機會，因為你已經管理過你有的那些系統，你本可以不需酬勞地管理那些日逐一日地運行的系統。但還是有一些面試官，願意拿一筆很不錯的薪水來找一些人去管理他們的系統。目前，系統和網絡管理的失業率幾乎為零，但是美國勞工統計局估計到 2024 年該領域將持續 ",-1)),e(o,{href:"https://www.bls.gov/ooh/Computer-and-Information-Technology/Network-and-computer-systems-administrators.htm#tab-1"},{default:n(()=>[...t[0]||(t[0]=[l("9% 的增長",-1)])]),_:1}),t[2]||(t[2]=l("。",-1))]),t[23]||(t[23]=a('<p>你可能會問，自動化運維怎麼樣？大概你已經聽一些系統管理員説過，他們打算如何來自動化他們所有的工作，或者，他們如何在一個 shell 腳本里自動化完成他們前任者的工作。你聽過的有多少成功的？自動化了某個任務，就會有更多的東西需要自動化。</p><p>如果你參加過系統管理者會議或觀看過他們的視頻，你會發現這是一個需要新鮮血液的領域。不僅僅是明顯的缺少年輕人，而且相當地性別和種族不平等。雖然有點兒跑題，但是多樣性已經被證明可以提高系統管理員非常感興趣的自我恢復力、解決問題的能力，創新力和決策力。</p><h3 id="我要成為一名系統管理員嗎" tabindex="-1">我要成為一名系統管理員嗎？ <a class="header-anchor" href="#我要成為一名系統管理員嗎" aria-label="Permalink to “我要成為一名系統管理員嗎？”">​</a></h3><p>有人要你，但是你要做系統管理工作嗎？如果你生活在一個第一世界國家，每年 70,000 美元的收入看上去是一個可以感到幸福的標準收入，或者説至少減少了大部分的與錢相關的壓力。系統和網絡管理員的中位年度收入是 80,000 美元，很容易達標，儘管明顯有些人賺的更少或更多。</p><p>你曾經免費做過一些系統管理工作嗎？我們大多數人都多多少少地管理一些設備，但是那並不代表你喜歡管理它。如果你曾經在你家的網絡中添加了一些服務器，你就是一個備選的系統管理員。你想要為自己的孩子添加一個“我的世界”的遊戲服務器麼，所以你用樹莓派搭建了一個？也許是時候來考慮通過做這樣的工作來獲取報酬了。</p><p>作為一份需要全面知識的工作，系統管理工作有很大的跨度。各種行業和各種規模的公司都需要系統管理員。大多數的位於市區裏的公司需要一些現場上班的人員，但是遠程辦公也有很大的可能性。</p><p>每個人都是免費地用開源軟件工作，但是，作為系統管理員，你也可以計酬工作。系統管理員經常把對開源項目做貢獻、支持開源供應商、使用各種各樣的有趣而強大的開源軟件為他們日常工作的一部分。</p><p>最後，談一下社區。以我多年的經驗來看，找到一個歡迎新人的、鼓勵參與的、氣氛友好的、彼此幫助的社區是非常難的。系統管理員給人的刻板印象就是性情乖戾，但是我感覺現在這只不過是個過時的笑話。現在大多數的系統管理員積極地回應各種形式的有建設性的反饋，尤其是歡迎新手。我們總是能敏鋭的察覺到各種各樣的入門級問題，並且熱心於解決它們。我們是一個有深度的、興趣廣泛的社區。問一下一個系統管理員在工作之餘都幹了些什麼，你肯定會感到吃驚。</p><h3 id="那麼-我要從哪兒開始" tabindex="-1">那麼，我要從哪兒開始？ <a class="header-anchor" href="#那麼-我要從哪兒開始" aria-label="Permalink to “那麼，我要從哪兒開始？”">​</a></h3><p>如果你被説服了，首先有個好消息。與許多技術類職業相比，從不是直接相關的四年制學歷轉為系統管理員是可能的。事實上，全世界有四年本科學歷的系統管理員相對較少，所以不用太擔心這個。對於現在的白領工作，學歷確實有用，而且越相關越好。與其他的技術類職業相比，這兒有一個很自然的入門級別的職位：技術支持。</p><p>對系統管理工作的候選人來説有個壞消息是真的，在技術類領域（甚至非技術類領域）：僱主在尋找有多年經驗的和有高學歷的人，即便是在入門級別的崗位上。僱主是刻薄的，僱主不會花錢給你培訓。不過稍嫌安慰的是，這些問題在人才市場上是非常普遍的，所以不管你找什麼工作都得面對這種問題。</p><p>系統管理工作可以作為其他 IT 領域的起點。比如：網絡管理、資料庫管理、網站可靠性工程師（SRE），再遠一些的也有，軟件工程師、質量保證（QA）、IT 管理。</p><p>系統管理工作的具體情況，包括其刻板的印象和一些明顯的方面以及不明顯的方面，是未來我們的文章的主題。我們也會涵蓋這個領域可能會改變的重要方面，提供一些方法來評估和比較系統管理職位，以及在面試中問到的一些重要問題。</p>',13)),s("p",null,[t[4]||(t[4]=l("如果你對加入這個領域有興趣，可以考慮加入",-1)),e(o,{href:"https://lopsa.org/"},{default:n(()=>[...t[3]||(t[3]=[l("專業系統管理者聯盟",-1)])]),_:1}),t[5]||(t[5]=l("（LOPSA），我在這個組織任董事會成員。會員資格是你負擔得起的（可能由您的僱主負責），而學生免費。成為 LOPSA 會員，是找到同行們和與有各種經驗、各種行業和工作環境中的人員討論職業生涯的絕佳方式。",-1))]),t[24]||(t[24]=s("p",null,"（題圖 : Jason Baker, CC BY-SA 4.0）",-1)),t[25]||(t[25]=s("hr",null,null,-1)),t[26]||(t[26]=s("p",null,"作者簡介：",-1)),t[27]||(t[27]=s("p",null,"Paul English - 他是 PreOS 安全公司的首席執行官，也是專業系統管理員聯盟的董事會成員，該專業系統管理員聯盟是一個非營利性專業協會，從 2015 年至今致力於提升系統管理工作實踐。 Paul 在 1998 年獲得了伍斯特理工學院的計算機學士學位。自 1996 年以來，Paul 一直是 UNIX 和 Linux 系統管理員和許多場合冠以 IT 之名的那個人。最近他在管理一些系統管理員。",-1)),t[28]||(t[28]=s("hr",null,null,-1)),s("p",null,[t[7]||(t[7]=l("via: ",-1)),e(o,{href:"https://opensource.com/article/17/7/why-become-sysadmin"},{default:n(()=>[...t[6]||(t[6]=[l("https://opensource.com/article/17/7/why-become-sysadmin",-1)])]),_:1})]),s("p",null,[t[11]||(t[11]=l("作者：",-1)),e(o,{href:"https://opensource.com/users/penglish"},{default:n(()=>[...t[8]||(t[8]=[l("Paul English",-1)])]),_:1}),t[12]||(t[12]=l(" 譯者：",-1)),e(o,{href:"https://github.com/sugarfillet"},{default:n(()=>[...t[9]||(t[9]=[l("sugarfillet",-1)])]),_:1}),t[13]||(t[13]=l(" 校對：",-1)),e(o,{href:"https://github.com/wxy"},{default:n(()=>[...t[10]||(t[10]=[l("wxy",-1)])]),_:1})]),s("p",null,[t[16]||(t[16]=l("本文由 ",-1)),e(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[14]||(t[14]=[l("LCTT",-1)])]),_:1}),t[17]||(t[17]=l(" 原創編譯，",-1)),e(o,{href:"https://linux.cn/"},{default:n(()=>[...t[15]||(t[15]=[l("Linux中國",-1)])]),_:1}),t[18]||(t[18]=l(" 榮譽推出",-1))])])}const L=r(d,[["render",m]]);export{P as __pageData,L as default};
